import { Context } from '<workspace>/src/context'
import { setCookie } from '<workspace>/src/helper/cookie'

const req = () => new Request('http://localhost/')

// A: c.header() before any c.res access, then assigning a raw Response
{
  const c = new Context(req())
  c.header('X-Prepared', 'yes')
  c.res = new Response('hi')
  console.log('A prepared-header survives raw assignment:', c.res.headers.get('X-Prepared'))
}

// B: c.res read first, then raw Response assignment
{
  const c = new Context(req())
  c.res
  c.header('X-Prepared', 'yes')
  c.res = new Response('hi')
  console.log('B prepared-header after reading c.res:', c.res.headers.get('X-Prepared'))
}

// C: re-wrap (compress style) preserves cookies exactly once
{
  const c = new Context(req())
  setCookie(c, 'a', '1')
  c.res = c.text('body')
  const cookiesBefore = c.res.headers.getSetCookie()
  c.res = new Response(c.res.body, c.res)
  console.log('C before:', JSON.stringify(cookiesBefore), 'after re-wrap:', JSON.stringify(c.res.headers.getSetCookie()))
}

// D: new Response carries its own Set-Cookie while context already has cookies
{
  const c = new Context(req())
  setCookie(c, 'ctx', '1')
  c.res = c.text('body')
  c.res = new Response('raw', { headers: { 'set-cookie': 'fresh=2; Path=/' } })
  console.log('D cookies after assigning response with own cookie:', JSON.stringify(c.res.headers.getSetCookie()))
}

// E: content-type skip + regular header override direction
{
  const c = new Context(req())
  c.header('Content-Type', 'text/context')
  c.header('X-Old', 'context-value')
  c.res = new Response('raw', { headers: { 'content-type': 'application/json', 'x-old': 'response-value', 'x-new': 'only-in-response' } })
  console.log('E content-type:', c.res.headers.get('content-type'))
  console.log('E x-old (context vs response):', c.res.headers.get('x-old'))
  console.log('E x-new:', c.res.headers.get('x-new'))
}

// F: get() view of merged multi set-cookie
{
  const c = new Context(req())
  c.header('set-cookie', 'one=1', { append: true })
  c.header('set-cookie', 'two=2', { append: true })
  c.res = new Response('raw', { headers: { 'set-cookie': 'three=3' } })
  console.log('F getSetCookie:', JSON.stringify(c.res.headers.getSetCookie()), '| get():', c.res.headers.get('set-cookie'))
}

