import { Context } from '<workspace>/src/context'
import { setCookie } from '<workspace>/src/helper/cookie'

const req = () => new Request('http://localhost/')

// E2: context headers set AFTER c.res is materialized, then raw Response assignment
{
  const c = new Context(req())
  c.res
  c.header('Content-Type', 'text/context')
  c.header('X-Old', 'context-value')
  c.res = new Response('raw', {
    headers: { 'content-type': 'application/json', 'x-old': 'response-value', 'x-new': 'only-in-response' },
  })
  console.log('E2 content-type:', c.res.headers.get('content-type'))
  console.log('E2 x-old (context vs response):', c.res.headers.get('x-old'))
  console.log('E2 x-new:', c.res.headers.get('x-new'))
}

// F2: multiple context cookies + response cookie, after c.res materialized
{
  const c = new Context(req())
  c.res
  setCookie(c, 'one', '1')
  setCookie(c, 'two', '2')
  c.res = new Response('raw', { headers: { 'set-cookie': 'three=3' } })
  console.log('F2 getSetCookie:', JSON.stringify(c.res.headers.getSetCookie()))
  console.log('F2 get():', c.res.headers.get('set-cookie'))
}

// G: empty cookies on context + response cookies -> response cookies dropped by delete+append loop?
{
  const c = new Context(req())
  c.res
  c.res = new Response('raw', { headers: [['set-cookie', 'keep=1'], ['set-cookie', 'keep=2']] })
  console.log('G getSetCookie:', JSON.stringify(c.res.headers.getSetCookie()))
}

// H: c.header then raw response, then c.finalized check
{
  const c = new Context(req())
  c.header('X-Prepared', 'yes')
  c.res = new Response('hi')
  console.log('H finalized:', c.finalized, '| prepared header:', c.res.headers.get('X-Prepared'))
}

// I: header() after finalized assignment re-wraps and keeps cookies
{
  const c = new Context(req())
  c.res = new Response('a', { headers: [['set-cookie', 's=1; Path=/']] })
  c.header('X-After', 'v')
  console.log('I cookies after header():', JSON.stringify(c.res.headers.getSetCookie()), '| X-After:', c.res.headers.get('x-after'))
}

